export function translatePhrase(frenchText, targetLang) {
  if (!frenchText || targetLang === 'FR') return frenchText;
  const clean = frenchText.trim();
  
  // Exact match
  if (MASTER_PHRASES[clean] && MASTER_PHRASES[clean][targetLang]) {
    return MASTER_PHRASES[clean][targetLang];
  }
  
  // Case-insensitive / normalized match
  const lower = clean.toLowerCase();
  for (const [k, translations] of Object.entries(MASTER_PHRASES)) {
    if (k.toLowerCase() === lower && translations[targetLang]) {
      return translations[targetLang];
    }
  }
  
  return null;
}
